const prefixes={"day": ["Jour", "Día", "Dia", "Ngày", "일차", "Tag"], "submissions": ["envois", "envíos", "envios", "lượt gửi", "건 제출", "Einreichungen"], "coverage": ["Période de jeu :", "Período de juego:", "Período de jogo:", "Kỳ trong game:", "게임 대상 기간:", "Spielzeitraum:"]};

const languages=['fr','es','pt','vi','ko','de'];
export let locale='en';
export function translate(text){
 if(locale==='en')return text;
 const trim=text.trim(), d=catalog[locale], i=languages.indexOf(locale);
 let value=d[trim];
 if(value===undefined){
  const day=trim.match(/^Day (\d+) · (.+)$/),sub=trim.match(/^(\d+) submissions$/),coverage=trim.match(/^Game coverage: (.+)$/),pts=trim.match(/^(\d+) PTS$/);
  if(day)value=(locale==='ko'?day[1]+prefixes.day[i]:prefixes.day[i]+' '+day[1])+' · '+translate(day[2]);
  else if(sub)value=sub[1]+' '+prefixes.submissions[i];
  else if(coverage)value=prefixes.coverage[i]+' '+coverage[1];
  else if(pts)value=pts[1]+' '+d.PTS;
  else if(trim.startsWith('Not open '))value=d['Not open']+' '+translate(trim.slice(9));
  else if(trim.startsWith('Submit '))value=d.Submit+' '+translate(trim.slice(7));
  else if(trim.startsWith('View '))value=d.View+' '+translate(trim.slice(5));
  else if(trim.includes(' · '))value=trim.split(' · ').map(s=>translate(s)).join(' · ');
 }
 return value===undefined?text:text.replace(trim,value);
}
export function initLanguages(refresh){
 const originals=new WeakMap();
 const observer=new MutationObserver(apply);
 function apply(){
  observer.disconnect();
  const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let node;
  while(node=walker.nextNode()){
   if(node.parentElement.closest('script,style,select,code,time,.code,.player-name,#matchup,input'))continue;
   const old=originals.get(node);const source=old&&node.nodeValue===old.output?old.source:node.nodeValue;
   const output=translate(source);originals.set(node,{source,output});if(output!==node.nodeValue)node.nodeValue=output;
  }
  for(const el of document.querySelectorAll('[aria-label]')){const source=el.dataset.originalLabel||el.getAttribute('aria-label');el.dataset.originalLabel=source;el.setAttribute('aria-label',translate(source));}
  observer.observe(document.body,{childList:true,subtree:true,characterData:true});
 }
 document.getElementById('language').onchange=event=>{locale=event.target.value;document.documentElement.lang=locale;refresh();apply();};
 apply();
}

